mapper.select:
SELECT start_ms, end_ms, transcript AS text
  FROM transcripts
 WHERE session_id = #{sessionId}
   AND start_ms < #{endMs}
   AND end_ms > #{startMs}
 ORDER BY start_ms ASC, id ASC

SELECT sent_at, message AS text, sentiment_label
  FROM chat_messages
 WHERE session_id = #{sessionId}
   AND sent_at >= #{startedAt}
   AND sent_at < #{endedAt}
 ORDER BY sent_at ASC, id ASC

SELECT detected_at, risk_level AS level, risk_category AS category, advice
  FROM risk_events
 WHERE session_id = #{sessionId}
   AND detected_at >= #{startedAt}
   AND detected_at < #{endedAt}
 ORDER BY detected_at ASC, id ASC

mapper.update:
UPDATE triggers
   SET analyzed_at = #{analyzedAt}, analysis_status = 'FAILED',
       analysis_error = #{error}
 WHERE id = #{triggerId}
   AND analysis_status IN ('PENDING', 'NOT_REQUESTED')

mapper.select:
SELECT NOT EXISTS (
    SELECT 1 FROM triggers
     WHERE session_id = #{sessionId}
       AND analysis_status NOT IN ('COMPLETED', 'FAILED')
)

