UPDATE reports
   SET status = 'COMPLETED', summary = #{summary}, generated_at = #{generatedAt}
 WHERE id = #{reportId} AND status = 'PROCESSING'

UPDATE reports
   SET status = 'PARTIAL', summary = #{summary}, generated_at = #{generatedAt}
 WHERE id = #{reportId} AND status = 'PROCESSING'
